import{_ as e,o as i,c as t,a2 as s}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"2019-04-18 :: Ceph Performance meeting","description":"","frontmatter":{"title":"2019-04-18 :: Ceph Performance meeting","date":"2019-04-18T00:00:00.000Z","updated":"2019-04-23T00:00:00.000Z","tags":["Ceph","分布式存储","性能优化","RocksDB","稳定性和可靠性"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-04-18_-_-_Ceph_Performance_meeting.md","filePath":"posts/2019/2019-04-18_-_-_Ceph_Performance_meeting.md","lastUpdated":1780460162000}'),o={name:"posts/2019/2019-04-18_-_-_Ceph_Performance_meeting.md"};function r(n,l,a,p,u,_){return i(),t("div",null,[...l[0]||(l[0]=[s('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间</strong>： 2019年4月18日</p><p><strong>参会人员</strong>： Adam（Ceph研发人员），其他Ceph团队成员</p><p><strong>会议内容</strong>：</p><p><strong>1. Pull Requests审核</strong></p><ul><li><strong>新提交的Pull Requests</strong>： <ul><li>一项通过在用户空间而非内核空间拉取事件的Pull Requests，实现了异步消息传递性能的提升。</li><li>一项优化UTF-8检查的Pull Requests，旨在提高系统性能。</li></ul></li><li><strong>已审核的Pull Requests</strong>： <ul><li>推迟延迟请求的Pull Requests，由Jason审核。</li><li>优化默认垃圾回收策略的Pull Requests，已解决先前存在的问题。</li></ul></li></ul><p><strong>2. Adam的RocksDB工作</strong></p><ul><li>Adam测试了将RocksDB数据库分割成多个列族对性能的影响。</li><li>测试结果表明，分割列族可以带来性能提升，最高可达29%。</li><li>Adam探讨了列族大小和写前锁对性能的影响，发现更大的写前锁和更少的列族可以显著提升性能。</li></ul><p><strong>3. RocksDB的压缩和扩展</strong></p><ul><li>团队讨论了RocksDB的压缩和扩展问题，并探讨如何通过调整配置来优化性能。</li><li>Adam提出，通过调整写前锁大小和列族配置，可以减少数据移动，提高压缩效率。</li></ul><p><strong>4. Ceph性能和稳定性</strong></p><ul><li>团队讨论了Ceph的性能和稳定性问题，并探讨如何改进系统性能和可靠性。</li><li>Adam提出，通过增加超时时间和优化超时策略，可以避免因长时间等待而导致的服务中断。</li></ul><p><strong>5. 其他议题</strong></p><ul><li>团队讨论了其他议题，包括： <ul><li>MDS缓存内存限制</li><li>内存自动调优</li><li>集群性能测试</li></ul></li></ul><p><strong>后续行动计划</strong>：</p><ul><li>Adam将继续测试RocksDB分割列族对性能的影响，并优化相关配置。</li><li>团队将继续改进Ceph的性能和稳定性。</li><li>团队将继续关注其他议题，并制定相应的解决方案。</li></ul><p><strong>关键词</strong>：</p><ul><li>Pull Requests</li><li>RocksDB</li><li>列族</li><li>写前锁</li><li>压缩</li><li>扩展</li><li>Ceph</li><li>性能</li><li>稳定性</li><li>MDS</li><li>内存自动调优</li></ul>',18)])])}const m=e(o,[["render",r]]);export{c as __pageData,m as default};
